// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.screenimport timber.log.Timberimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Real UI Element Detector (Module 6 v4 — Step 6.6, v1 minimal implementation). * * A [UiElementDetector] that delegates to the active [AccessibilityUiElementDetector] * when the accessibility service is bound; otherwise returns an empty list * (never returns fake/stub elements). * * ## Why a thin wrapper * * [AccessibilityUiElementDetector] is the production detector that walks the * [android.view.accessibility.AccessibilityNodeInfo] tree. It needs the user * to have granted `BIND_ACCESSIBILITY_SERVICE` permission to NOUS. Until that * permission is granted, this detector returns an empty list (instead of * fabricating UI elements — fabricating would risk the screen reader speaking * wrong information to a blind user). * * ## Fallback * * When the accessibility service is unavailable, downstream callers * ([ScreenUnderstandingEngine]) fall back to OCR-only screen reading via * [com.roshan.persona.vision.ocr.OcrEngine] — see * [com.roshan.persona.vision.infrastructure.FallbackChainOrchestrator.runScreenUnderstandingChain]. * * @see AccessibilityUiElementDetector */@Singletonclass RealUiElementDetector @Inject constructor(    private val accessibilityDetector: AccessibilityUiElementDetector,) : UiElementDetector {    override suspend fun detect(imageBytes: ByteArray): List<UiElement> {        // Delegate to the accessibility-tree-based detector. When no        // AccessibilityService is registered, it returns an empty list        // (no fabricated elements).        return try {            accessibilityDetector.detect(imageBytes)        } catch (t: Throwable) {            Timber.tag(TAG).w("Accessibility-based UI detection failed — returning empty list.", t)            emptyList()        }    }    private companion object {        private const val TAG = "RealUiElementDetector"    }}